#!/usr/bin/env node
/**
 * build/ncert-hsec-humanities.mjs — NCERT History, Geography and Political
 * Science, Classes XI–XII.
 *
 * SUBJECT PLACEMENT: Geography and Political Science are subjects in their own
 * right from age 14 (user decision, 2026-07-18), matching the treatment given
 * to Physics, Chemistry and Biology. Below 14 their content stays under the
 * Social Studies umbrella — see build/subject-split-geography-polsci.mjs, which
 * reconciles topics minted before that decision.
 *
 * History XII is organised by source type rather than chronology ("Themes in
 * Indian History"), so its topics are framed around reading a class of evidence.
 * Descriptions are Marble-authored factual scope summaries (no NCERT text).
 * Idempotent.
 */

import { integrateNcertHsec, mintNs, s, topic } from './ncert-hsec.mjs';

